{
  "mode": "ask",
  "question": "Since you are the only one riding and working on the bike, are you the only person who decides if the tyres are safe, or is there any official sign-off or log you have to keep?",
  "asks_about": "authority",
  "unresolved": [
    "Whether there is any external authority or if the rider is the sole sign-off for the safety check"
  ],
  "understanding": "You check both tyres before every ride, pumping them to the maximum pressure printed on the sidewall and checking for splits. You use a pump gauge and take photos of the gauge and sidewall to confirm the pressure.",
  "draft": null
}
